namespace ghidra.app.util;






using docking;
using docking;
using docking.widgets;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.layout;
using ghidra.util.task;

/**
 * Class for choosing a namespace
 */
public class NamespaceChooserDialog : DialogComponentProvider {

	private DropDownSelectionTextField<Namespace> dropDownField;
	private NamespaceDropDownModel namespaceModel;
	private Namespace chosenNamespace;

	public NamespaceChooserDialog() : base("Namespace Chooser")
    {
		namespaceModel = new NamespaceDropDownModel();
		addWorkPanel(buildWorkPanel());
		addOKButton();
		addCancelButton();
	}

	public void setText(string text) {
		dropDownField.setText(text);
	}

	public Namespace getNamespace(Program program) {
		List<Namespace> namespaces = gatherNamespaces(program);
		if (namespaces == null) {
			// user cancelled while gathering namespaces
			return null;
		}
		namespaceModel.setNamespaces(namespaces);
		DockingWindowManager.showDialog(this);
		return chosenNamespace;
	}

	public string getNamespaceText() {
		return dropDownField.getText();
	}

	/* @Override */
	protected void okCallback() {
		chosenNamespace = dropDownField.getSelectedValue();
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		chosenNamespace = null;
		dropDownField.setText("");
		close();
	}

	private List<Namespace> gatherNamespaces(Program program) {
		GatherNamespacesTask task = new GatherNamespacesTask(program);
		TaskLauncher.launch(task);
		return task.getNamespaces();
	}

	private JComponent buildWorkPanel() {
		JPanel panel = new JPanel(new PairLayout());
		panel.add(new JLabel("Namespace:  "));

		dropDownField = new(namespaceModel);
		dropDownField.setShowMatchingListOnEmptyText(true);
		panel.add(dropDownField);
		panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		return panel;
	}

	private static class GatherNamespacesTask : Task {
		private List<Namespace> namespaces;
		private Program program;

		GatherNamespacesTask(Program program) : base("Gather Namespaces")
    {
			this.program = program;
		}

		/* @Override */
		public void run(TaskMonitor monitor)
    {
			List<Namespace> list = new();
			list.add(program.getGlobalNamespace());
			foreach (Symbol symbol in program.getSymbolTable().getDefinedSymbols()) {
				monitor.checkCancelled();
				if (!symbol.getSymbolType().isNamespace()) {
					continue;
				}
				object @object = symbol.getObject();
				if (@object is Function f && f.isThunk()) {
					continue;
				}
				list.add((Namespace) @object);
			}
			namespaces = list;
		}

		List<Namespace> getNamespaces() {
			return namespaces;
		}

	}

}
